import{_ as e,c as r,o as l,a1 as n}from"./chunks/framework.C3Hmo1as.js";const y=JSON.parse('{"title":"ChatGPT 中精准选择大模型完成各类研发任务","description":null,"frontmatter":{"title":"ChatGPT 中精准选择大模型完成各类研发任务","description":null,"date":"2026-09-13T00:00:00.000Z","tags":["ChatGPT","Prompt Engineering","AI Coding"]},"headers":[],"relativePath":"fullstack/chatgpt-model-selection-guide.md","filePath":"fullstack/chatgpt-model-selection-guide.md"}'),s={name:"fullstack/chatgpt-model-selection-guide.md"};function o(a,t,g,d,i,h){return l(),r("div",null,[...t[0]||(t[0]=[n('<p>在日常的 AI 辅助研发与复杂业务系统设计中，合理选择和切换 ChatGPT 的不同模型（如 Terra, Sol, Astra）不仅能大幅提升交付质量，还能有效管理额度与上下文窗口。本文将系统梳理 ChatGPT 的核心术语、模型消耗对比、场景选择及切换策略，为你提供一份即插即用的实战指南。</p><h2 id="模块一-基础认知与算力盘点" tabindex="-1">模块一：基础认知与算力盘点 <a class="header-anchor" href="#模块一-基础认知与算力盘点" aria-label="Permalink to &quot;模块一：基础认知与算力盘点&quot;">​</a></h2><h3 id="_1-核心术语与任务分类对齐" tabindex="-1">1. 核心术语与任务分类对齐 <a class="header-anchor" href="#_1-核心术语与任务分类对齐" aria-label="Permalink to &quot;1. 核心术语与任务分类对齐&quot;">​</a></h3><p>在与 AI 协同工作或编写提示词时，精准的术语能极大降低歧义，尤其应<strong>完全避开单独使用“Session”</strong>一词。以下是标准化术语中英对照表：</p><table tabindex="0"><thead><tr><th style="text-align:left;">目标对象 / 概念</th><th style="text-align:left;">推荐术语 (中英对照)</th><th style="text-align:left;">核心含义与场景示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>侧边栏里的一段聊天</strong></td><td style="text-align:left;"><strong>会话 (Thread)</strong></td><td style="text-align:left;">逻辑上的一个对话窗口，可包含多轮问答。</td></tr><tr><td style="text-align:left;"><strong>一次完整的问答交互</strong></td><td style="text-align:left;"><strong>轮 (Turn)</strong></td><td style="text-align:left;">从用户单次提问到 AI 的一次最终答复（期间可能包含多次隐式工具调用）。</td></tr><tr><td style="text-align:left;"><strong>跨越多个会话的持续目标</strong></td><td style="text-align:left;"><strong>任务 (Work Item / Task)</strong></td><td style="text-align:left;">具备明确业务目标的完整工作，如“股票停牌信息库与计算前置拦截”。</td></tr><tr><td style="text-align:left;"><strong>对某任务的局部修正</strong></td><td style="text-align:left;"><strong>第 N 轮返修 (N-th Round Revision)</strong></td><td style="text-align:left;">基于上一次交付物的修改，如“同一任务的第 1 轮返修审核”。</td></tr><tr><td style="text-align:left;"><strong>单次处理的文本容量</strong></td><td style="text-align:left;"><strong>上下文窗口 (Context Window)</strong></td><td style="text-align:left;">模型在单个 Thread 中能记住的历史信息上限，达到瓶颈时会触发自动压缩。</td></tr><tr><td style="text-align:left;"><strong>背景信息与约束集合</strong></td><td style="text-align:left;"><strong>事实依据 (Ground Truth / Facts)</strong></td><td style="text-align:left;">提供给 AI 的已确认业务规则、验收标准或不可推翻的前提条件。</td></tr></tbody></table><blockquote><p>💡 <strong>最佳表达范例</strong>：“请新建一个<strong>会话 (Thread)</strong>，但继续审核同一个跨会话<strong>任务 (Work Item)</strong>：<code>股票停牌信息库与计算前置拦截</code>。这是该任务的<strong>第 1 轮返修 (1st Round Revision)</strong>审核，不是新功能设计。”</p></blockquote><h3 id="_2-模型消耗速度与成本对比矩阵" tabindex="-1">2. 模型消耗速度与成本对比矩阵 <a class="header-anchor" href="#_2-模型消耗速度与成本对比矩阵" aria-label="Permalink to &quot;2. 模型消耗速度与成本对比矩阵&quot;">​</a></h3><p>模型的消耗通常分为<strong>API 计费</strong>与<strong>订阅额度池消耗</strong>两种逻辑，不可直接混为一谈。</p><h4 id="a-api-token-相对单价参考-以-terra-为基准" tabindex="-1">A. API Token 相对单价参考（以 Terra 为基准） <a class="header-anchor" href="#a-api-token-相对单价参考-以-terra-为基准" aria-label="Permalink to &quot;A. API Token 相对单价参考（以 Terra 为基准）&quot;">​</a></h4><p><em>注意：单价高不等于单任务绝对总价高，Astra 在复杂任务中可能以更少的输出 token 提前收敛。</em></p><table tabindex="0"><thead><tr><th style="text-align:left;">模型层级</th><th style="text-align:center;">输入价格 ($/M)</th><th style="text-align:center;">输出价格 ($/M)</th><th style="text-align:center;">相对 Terra 的价格倍率 (入 / 出)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>GPT-5.6 Terra</strong></td><td style="text-align:center;">2</td><td style="text-align:center;">12</td><td style="text-align:center;">1× / 1×</td></tr><tr><td style="text-align:left;"><strong>GPT-5.6 Sol</strong></td><td style="text-align:center;">4</td><td style="text-align:center;">20</td><td style="text-align:center;">2× / 1.67×</td></tr><tr><td style="text-align:left;"><strong>GPT-6 Astra</strong></td><td style="text-align:center;">10</td><td style="text-align:center;">50</td><td style="text-align:center;">5× / 4.17×</td></tr></tbody></table><h4 id="b-work-codex-订阅额度消耗强度估算" tabindex="-1">B. Work/Codex 订阅额度消耗强度估算 <a class="header-anchor" href="#b-work-codex-订阅额度消耗强度估算" aria-label="Permalink to &quot;B. Work/Codex 订阅额度消耗强度估算&quot;">​</a></h4><p><em>注意：每周额度和五小时额度同时生效，综合了上下文长度、工具调用、推理强度等因素，以下为同一任务下的近似消耗倍率：</em></p><table tabindex="0"><thead><tr><th style="text-align:left;">模型层级</th><th style="text-align:center;">相对 Terra 的额度消耗倍率</th><th style="text-align:left;">核心定位与匹配度</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>GPT-5.6 Luna</strong></td><td style="text-align:center;">~ 0.1×</td><td style="text-align:left;"><strong>极轻量</strong>：极短对话、重复任务、提取、分类、措辞微调。</td></tr><tr><td style="text-align:left;"><strong>GPT-5.6 Terra</strong></td><td style="text-align:center;">1×</td><td style="text-align:left;"><strong>日常主力</strong>：常规问答、基础代码编写、边界清晰的单轮审核。</td></tr><tr><td style="text-align:left;"><strong>GPT-5.5</strong></td><td style="text-align:center;">~ 1.7–2.5×</td><td style="text-align:left;"><strong>向下兼容</strong>：特定旧模型兼容场景，或已验证其表现更佳时。</td></tr><tr><td style="text-align:left;"><strong>GPT-5.6 Sol</strong></td><td style="text-align:center;">~ 2.0–2.5×</td><td style="text-align:left;"><strong>进阶骨干</strong>：跨模块推演、复杂逻辑实现、深度审查。</td></tr><tr><td style="text-align:left;"><strong>GPT-6 Astra</strong></td><td style="text-align:center;">~ 4.5–5.0×</td><td style="text-align:left;"><strong>最强推理</strong>：高风险、完全陌生、极难推理的端到端问题。</td></tr><tr><td style="text-align:left;"><strong>Codex Spark (5.3)</strong></td><td style="text-align:center;">独立池，不可换算</td><td style="text-align:left;"><strong>独立额度</strong>：按其自身限额和界面提示使用。</td></tr></tbody></table><h2 id="模块二-实操策略——选型、升级与上下文管理" tabindex="-1">模块二：实操策略——选型、升级与上下文管理 <a class="header-anchor" href="#模块二-实操策略——选型、升级与上下文管理" aria-label="Permalink to &quot;模块二：实操策略——选型、升级与上下文管理&quot;">​</a></h2><h3 id="_3-实际研发任务的模型首选与升级时机" tabindex="-1">3. 实际研发任务的模型首选与升级时机 <a class="header-anchor" href="#_3-实际研发任务的模型首选与升级时机" aria-label="Permalink to &quot;3. 实际研发任务的模型首选与升级时机&quot;">​</a></h3><p>在实际业务（如 QMT 量化交易系统、复杂并发系统）研发中，建议采用 <strong>70% Terra + 25% Sol + 5% Astra</strong> 的黄金配额策略。</p><table tabindex="0"><thead><tr><th style="text-align:left;">研发工作阶段 / 任务类型</th><th style="text-align:left;">首选默认模型</th><th style="text-align:left;">🚀 何时考虑升级模型 (Trigger)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>需求澄清、术语释疑</strong></td><td style="text-align:left;"><strong>Terra</strong> (低/中档)</td><td style="text-align:left;">仅简短文字可用 <strong>Luna</strong>；需追溯多份历史设计与代码事实时升 <strong>Sol</strong>。</td></tr><tr><td style="text-align:left;"><strong>架构推演、聊需求</strong></td><td style="text-align:left;"><strong>Terra</strong> (高档)</td><td style="text-align:left;">涉及跨模块合同、事务边界、历史语义用 <strong>Sol (高)</strong>；关键业务规则定稿用 <strong>Astra (中/高)</strong>。</td></tr><tr><td style="text-align:left;"><strong>编写开发任务设计文档</strong></td><td style="text-align:left;"><strong>Terra</strong> (高档)</td><td style="text-align:left;">涉及多阶段、多合同、前后端联动或数据迁移时升 <strong>Sol (高)</strong>。</td></tr><tr><td style="text-align:left;"><strong>拆分阶段、写阶段提示词</strong></td><td style="text-align:left;"><strong>Terra</strong> (高档)</td><td style="text-align:left;">具有复杂依赖链、需预判未来返工路径时升 <strong>Sol (高)</strong>。</td></tr><tr><td style="text-align:left;"><strong>一轮返修审核与 Diff 核对</strong></td><td style="text-align:left;"><strong>Terra</strong> (高档)</td><td style="text-align:left;">当任务仅需检查差异、跑聚焦测试、给 PASS/FAIL 且边界明确时。</td></tr><tr><td style="text-align:left;"><strong>深度代码审核与最终审计</strong></td><td style="text-align:left;"><strong>Sol</strong> (高档)</td><td style="text-align:left;">涉及原子事务、隐性业务语义、跨数据库链路或最终的独立审计时，直接上 <strong>Astra (高)</strong>。</td></tr></tbody></table><h3 id="_4-终极心法-模型与推理档位的平滑升级策略" tabindex="-1">4. 终极心法：模型与推理档位的平滑升级策略 <a class="header-anchor" href="#_4-终极心法-模型与推理档位的平滑升级策略" aria-label="Permalink to &quot;4. 终极心法：模型与推理档位的平滑升级策略&quot;">​</a></h3><p>在实际操作中，很多开发者会疑惑：“Terra 的「高」推理和 Sol 的「中」推理，到底哪个更强、哪个更耗额度？”</p><p><strong>结论先行</strong>：<strong>Terra「高」和 Sol「中」绝对不等价，且不存在官方固定的“额度换算比例”。</strong> 它们都会消耗同一个「通用每周使用限额」，但实际扣减量综合了模型基础消耗、推理档位、任务步骤数、读写文件量及上下文长度。千万不要将其理解为“每发一条固定扣 1 格”。</p><h4 id="a-双维驱动-模型能力-vs-推理档位" tabindex="-1">A. 双维驱动：模型能力 vs 推理档位 <a class="header-anchor" href="#a-双维驱动-模型能力-vs-推理档位" aria-label="Permalink to &quot;A. 双维驱动：模型能力 vs 推理档位&quot;">​</a></h4><p>要精准控制消耗，必须拆分理解两个核心维度：</p><ol><li><strong>模型层级 (Model)</strong>：决定了基础能力底线、速度与单位工作成本。在相同的 5 小时窗口内，预期可完成的任务数大致为：<strong>Luna ≫ Terra ≈ 2～2.5 倍 Sol ≫ Astra</strong>。</li><li><strong>推理档位 (Reasoning Level)</strong>：决定了该模型为当前任务投入的“思考深度”。选择「较高」、「极高」或「Ultra」必然增加额度消耗，但<strong>不保证结果一定更好</strong>。如果上下文缺失、任务描述模糊或未给足文件权限，无脑拉高推理档位纯属浪费。</li></ol><h4 id="b-核心模型定位与省流指南" tabindex="-1">B. 核心模型定位与省流指南 <a class="header-anchor" href="#b-核心模型定位与省流指南" aria-label="Permalink to &quot;B. 核心模型定位与省流指南&quot;">​</a></h4><p>除 Codex Spark 外，其余主模型均共享通用额度池。以下是各模型的精准定位：</p><table tabindex="0"><thead><tr><th>模型选择</th><th>核心适用场景 (以 QMT 等复杂工程为例)</th><th>额度管理与省流建议</th></tr></thead><tbody><tr><td><strong>Luna</strong></td><td>查找代码、提取信息、重复性小改、短文本。</td><td><strong>极致省流</strong>：先用它处理明确且低风险的细碎任务。</td></tr><tr><td><strong>Terra</strong></td><td>常规功能修改、单模块排查、一般测试修复。</td><td><strong>日常首选</strong>：默认使用「中」档，不够再升「高」档。</td></tr><tr><td><strong>Sol</strong></td><td>跨模块功能、较复杂业务逻辑、长链路分析。</td><td><strong>关键攻坚</strong>：核心开发任务默认「中」档，深挖时才用「高」档。</td></tr><tr><td><strong>Astra</strong></td><td>棘手 Bug、陌生架构、重要设计决策。</td><td><strong>终极底牌</strong>：留给真正卡住的问题，优先尝试「较轻」或「中」档。</td></tr><tr><td><strong>GPT-5.5</strong></td><td>较旧一代模型。</td><td>除非已验证其在特定任务表现更好，否则不建议优先选择。</td></tr><tr><td><strong>Codex Spark</strong></td><td>快速、轻量的局部编码工作。</td><td>💎 <strong>独立额度池</strong>：拥有单独的 5小时/每周额度，<strong>不消耗通用池</strong>！强烈推荐将细碎工作迁移至此。</td></tr></tbody></table><h4 id="c-黄金法则-平滑升级的-s-o-p" tabindex="-1">C. 黄金法则：平滑升级的 S.O.P <a class="header-anchor" href="#c-黄金法则-平滑升级的-s-o-p" aria-label="Permalink to &quot;C. 黄金法则：平滑升级的 S.O.P&quot;">​</a></h4><p>最省额度的核心原则并不是“永远选最低端的模型”，而是：<strong>用能一次成功的最低组合。</strong> 用低阶模型反复报错返工三次，其消耗和时间成本往往远超用 Sol「中」档一次性解决。</p><p>强烈建议采用以下「递进式升级路径」，每次遇到瓶颈，<strong>只升级一个维度</strong>：</p><blockquote><p>🟢 <strong>Terra (中)</strong> ➔ 🟡 <strong>Terra (高)</strong> ➔ 🟠 <strong>Sol (中)</strong> ➔ 🔴 <strong>Sol (高)</strong> ➔ 🟣 <strong>Astra (较轻 / 中)</strong></p></blockquote><ul><li><strong>常规起手 (Terra + 中)</strong>：常规接口、前端组件、小范围 Bug、测试失败排查。</li><li><strong>单点深化 (Terra + 高)</strong>：单模块内具备一定复杂度，如交易逻辑边界、配置链路、较复杂的测试修复。</li><li><strong>跨界梳理 (Sol + 中)</strong>：跨前后端/数据库的多模块任务。切忌一上来就用高档，先让它做定位与首轮实现。</li><li><strong>硬核重构 (Sol + 高)</strong>：首轮不可靠、反复返工、需要复杂回归、涉及并发/状态机/隐蔽数据问题。</li><li><strong>降维打击 (Astra + 较轻/中)</strong>：彻底卡住或需要高质量技术判断时。注意：<strong>Astra 的较低推理档位，往往强于 Sol 的高档位</strong>，优先尝试跨模型而不是盲目死磕原模型的 Ultra 档。</li></ul><p><strong>💡 避坑总结</strong>：绝对不要从 <code>Terra (中)</code> 直接跳跃到 <code>Astra (Ultra)</code>。面对庞大的开发任务，最佳实践是：先用 Terra/Sol 完成范围确认和任务拆解，<strong>最后只把最难的那一个子问题单独抛给 Astra</strong>，这才是最高效的额度管理艺术。</p><h3 id="_5-模型切换与新建会话-thread-的时机选择" tabindex="-1">5. 模型切换与新建会话 (Thread) 的时机选择 <a class="header-anchor" href="#_5-模型切换与新建会话-thread-的时机选择" aria-label="Permalink to &quot;5. 模型切换与新建会话 (Thread) 的时机选择&quot;">​</a></h3><p>提升模型能力<strong>不等于</strong>必须新建会话；但改变任务事实、交付物或审查视角时，<strong>必须</strong>新建会话。</p><h4 id="a-基于任务边界的判断矩阵" tabindex="-1">A. 基于任务边界的判断矩阵 <a class="header-anchor" href="#a-基于任务边界的判断矩阵" aria-label="Permalink to &quot;A. 基于任务边界的判断矩阵&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">当前场景状态</th><th style="text-align:left;">执行策略建议</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>仍在处理同一目标，只是发现难度增加</strong></td><td style="text-align:left;">🟢 <strong>留在原 Thread</strong>，直接原地升级模型 (Terra → Sol → Astra)。</td></tr><tr><td style="text-align:left;"><strong>只是追问术语、补一两个约束条件</strong></td><td style="text-align:left;">🟢 <strong>留在原 Thread</strong>，保持上下文连贯。</td></tr><tr><td style="text-align:left;"><strong>审核后按问题开始返修代码</strong></td><td style="text-align:left;">🟡 <strong>留原 Thread 或新开均可</strong>；改动复杂时优先留原 Thread 保持代码脉络。</td></tr><tr><td style="text-align:left;"><strong>从需求讨论阶段转入正式写开发文档</strong></td><td style="text-align:left;">🟠 <strong>倾向于新建 Thread</strong>，避免早期发散讨论干扰文档生成。</td></tr><tr><td style="text-align:left;"><strong>核心结论或前提被推翻 (如发现严重误解)</strong></td><td style="text-align:left;">🔴 <strong>必须新建 Thread</strong>。附上“当前有效事实与新结论”，明确旧结论已作废。</td></tr><tr><td style="text-align:left;"><strong>需要独立视角的代码审核 / 验收</strong></td><td style="text-align:left;">🔴 <strong>必须新建 Thread</strong>。附上验收标准、设计文档和审查范围，防止受原思路污染。</td></tr></tbody></table><h4 id="b-基于对话轮数-turns-的实用规则" tabindex="-1">B. 基于对话轮数 (Turns) 的实用规则 <a class="header-anchor" href="#b-基于对话轮数-turns-的实用规则" aria-label="Permalink to &quot;B. 基于对话轮数 (Turns) 的实用规则&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">当前 Thread 轮数</th><th style="text-align:left;">操作建议</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>0 – 10 轮</strong></td><td style="text-align:left;">绝不要仅仅因为轮数多而新建 Thread。</td></tr><tr><td style="text-align:left;"><strong>10 – 20 轮</strong></td><td style="text-align:left;">若目标未变则继续。<strong>技巧</strong>：让模型先输出一份“当前事实、已定决策、未决问题”摘要作为锚点。</td></tr><tr><td style="text-align:left;"><strong>20 – 30 轮以上</strong></td><td style="text-align:left;">检查是否跨越了研发阶段（如设计进入了测试）。若跨阶段，强烈建议新建 Thread。</td></tr><tr><td style="text-align:left;"><strong>任何轮数</strong></td><td style="text-align:left;">只要发现历史记录中积累了<strong>大量已作废结论</strong>，立即止损并新建 Thread，效率远超原地纠错。</td></tr></tbody></table><h3 id="_6-⚠️-核心注意事项与避坑指南" tabindex="-1">6. ⚠️ 核心注意事项与避坑指南 <a class="header-anchor" href="#_6-⚠️-核心注意事项与避坑指南" aria-label="Permalink to &quot;6. ⚠️ 核心注意事项与避坑指南&quot;">​</a></h3><ol><li><strong>不要试图用 Astra 在“被污染”的上下文中强行修补</strong>： 如果 Terra 已经产生了根深蒂固的错误业务理解（如：误将股票池快照当作资格条件），切到 Astra 往往无济于事。<strong>最稳妥的做法</strong>：新建 Thread，将正确的业务规则、明确禁止的旧理解一并丢给 Astra。</li><li><strong>谨慎使用最高推理档位 (xhigh)</strong>： 不要常态化开启最高推理档位。高推理不仅指数级消耗额度，在指令和事实文件不完整的情况下，反而容易导致模型“过度脑补”。官方准则：<strong>先确保指令、文件和上下文完整，再提高推理强度。</strong></li><li><strong>把业务规则写死在 Prompt 里</strong>： 为了成本控制，在进行常规的 <strong>Terra (high)</strong> 审核时，尽量将关键的事务边界、调度逻辑等业务不变量“写死”在提示词中，降低模型自行推演产生的幻觉风险。</li></ol><h2 id="模块三-高阶工作流-工作区生态分层与-agent-协同" tabindex="-1">模块三：高阶工作流：工作区生态分层与 Agent 协同 <a class="header-anchor" href="#模块三-高阶工作流-工作区生态分层与-agent-协同" aria-label="Permalink to &quot;模块三：高阶工作流：工作区生态分层与 Agent 协同&quot;">​</a></h2><p>在复杂的项目实践（如 QMT 量化项目或大型全栈应用）中，仅靠切分模型是不够的，还需要结合架构工具进行合理分层。</p><h3 id="a-最实用的生态分层矩阵" tabindex="-1">A. 最实用的生态分层矩阵 <a class="header-anchor" href="#a-最实用的生态分层矩阵" aria-label="Permalink to &quot;A. 最实用的生态分层矩阵&quot;">​</a></h3><p>OpenAI 官方架构将项目指令、记忆、Skills、子 Agent 等视为互补层，而非互斥的工作方式。Git worktree 的核心价值则是让独立任务并行且不互相干扰：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层次结构</th><th style="text-align:left;">它解决什么问题 (核心功能)</th><th style="text-align:left;">⚠️ 不应拿来替代什么 (防踩坑)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>项目 / Workspace</strong></td><td style="text-align:left;">共享仓库、<code>AGENTS.md</code>、技能 (Skill)、工具、长期规则。</td><td style="text-align:left;"><strong>不能</strong>指望它让不同对话“自动共享”全部的推断与决策过程。</td></tr><tr><td style="text-align:left;"><strong>Task / Thread</strong></td><td style="text-align:left;">围绕一个 <strong>明确交付物</strong> 持续推理和执行。</td><td style="text-align:left;"><strong>不适合</strong>塞入整个项目从头到尾的所有杂乱历史。</td></tr><tr><td style="text-align:left;"><strong>子 Agent</strong></td><td style="text-align:left;">并行完成彼此独立、边界清楚的子问题。</td><td style="text-align:left;"><strong>不适合</strong>处理强依赖、持续互相影响的交叉链路实现。</td></tr><tr><td style="text-align:left;"><strong>Worktree</strong></td><td style="text-align:left;">隔离并发代码写入，避免不同任务互相踩文件。</td><td style="text-align:left;"><strong>不等于</strong>自动提升系统设计质量。</td></tr><tr><td style="text-align:left;"><strong>Skill (技能)</strong></td><td style="text-align:left;">固化反复出现的流程、约束和检查清单。</td><td style="text-align:left;"><strong>不应</strong>把一次性的业务判断硬编码进去。</td></tr></tbody></table><h3 id="b-团队协同与架构共识" tabindex="-1">B. 团队协同与架构共识 <a class="header-anchor" href="#b-团队协同与架构共识" aria-label="Permalink to &quot;B. 团队协同与架构共识&quot;">​</a></h3><ul><li><strong>隔离污染</strong>：不要把需求、设计、实现、报错、部署、审核无限塞进一个 task。项目变大后，作废的结论与不同阶段的上下文会发生严重的互相污染。</li><li><strong>按需 Agent 化</strong>：如果任务可并行且写入隔离，<code>子 Agent + Worktree</code> 效果极佳；但“为了多 agent 而多 agent”只会徒增系统协调成本和 Token 消耗。</li><li><strong>流程技能化</strong>：稳定不变的团队规矩（如“开发前必读文档”、“保护脏工作区”、“测试顺序”、“最终报告格式”）应做成 Skill，消灭重复提示词。</li><li><strong>人类总控兜底</strong>：总控 Agent 适合跑高度成熟的标准化流水线；但面对高风险业务项目，必须由人类牢牢把控 <strong>设计批准权</strong>、<strong>阶段切换权</strong> 与 <strong>最终审核权</strong>。</li></ul><h3 id="c-实战拆解-qmt-等复杂项目的任务切分法" tabindex="-1">C. 实战拆解：QMT 等复杂项目的任务切分法 <a class="header-anchor" href="#c-实战拆解-qmt-等复杂项目的任务切分法" aria-label="Permalink to &quot;C. 实战拆解：QMT 等复杂项目的任务切分法&quot;">​</a></h3><p>不再按“前端 / 后端”机械拆分会话，而是严格按 <strong>交付物和风险边界</strong> 拆分：</p><ol><li><strong>需求与设计 Task</strong>：澄清核心业务语义，最终形成/修改设计合同。常规用 <strong>Terra</strong>，逻辑复杂上 <strong>Sol</strong>。</li><li><strong>实施 Task</strong>：专注执行已批准的某单一阶段。强依赖环境下启用 <strong>Worktree</strong>，避免波及正在进行的其他功能修改。</li><li><strong>独立审核 Task (核心必做)</strong>：<strong>务必新开 Task</strong>，绝不继承实施过程中的“心理路径”。只提供设计文档、验收条件、Diff 范围与测试结果。以 <strong>Sol (高档)</strong> 为主，面对高风险业务上 <strong>Astra</strong>。</li><li><strong>返修 Task</strong>：针对最终审核清单做局部修改与回归。若边界明确，<strong>Terra (高档)</strong> 即可轻松应对。</li><li><strong>收敛子 Agent 权限</strong>：仅在“可独立验证的事项”启用子 Agent（例如“扫描所有提交入口”、“核对前端路由与菜单”、“补充测试覆盖矩阵”）。<strong>严禁</strong>放任多个 Agent 同时修改同一业务主链路或同一组关键文件。</li></ol><h3 id="d-新开-task-的标准-交接包" tabindex="-1">D. 新开 Task 的标准“交接包” <a class="header-anchor" href="#d-新开-task-的标准-交接包" aria-label="Permalink to &quot;D. 新开 Task 的标准“交接包”&quot;">​</a></h3><p><strong>牢记</strong>：同一项目下的新 Task 共享的仅仅是工作区代码和长期规则，而不是“你们之前的聊天记录”。每次新开 Task，都必须在开头给 AI 塞入一个结构化的“交接包”：</p><ul><li>🎯 <strong>当前目标</strong></li><li>✅ <strong>已批准、不可推翻的业务事实</strong></li><li>🚧 <strong>本次范围与严格禁止项</strong></li><li>📚 <strong>本次必读文档</strong></li><li>⚠️ <strong>当前工作区是否有未提交 (dirty) 的状态</strong></li><li>🧪 <strong>验收与测试要求</strong></li></ul><blockquote><p>💡 <strong>终极一句话工作法则：</strong><strong>项目承载长期规则；Task 承载一个交付物；Skill 承载可复用流程；子 Agent 承载可并行子问题；Worktree 承载并发写入隔离；人类承载业务决策与最终裁决。</strong></p></blockquote><h2 id="附录-跨平台生态-claude-code-等-的术语与机制映射" tabindex="-1">附录：跨平台生态（Claude Code 等）的术语与机制映射 <a class="header-anchor" href="#附录-跨平台生态-claude-code-等-的术语与机制映射" aria-label="Permalink to &quot;附录：跨平台生态（Claude Code 等）的术语与机制映射&quot;">​</a></h2><h3 id="_8-跨平台生态下的术语差异-claude-code-vs-chatgpt" tabindex="-1">8. 跨平台生态下的术语差异（Claude Code vs ChatGPT） <a class="header-anchor" href="#_8-跨平台生态下的术语差异-claude-code-vs-chatgpt" aria-label="Permalink to &quot;8. 跨平台生态下的术语差异（Claude Code vs ChatGPT）&quot;">​</a></h3><p>在多工具协同的实际研发中，你可能会同时使用 ChatGPT、Codex CLI 以及 Claude Code。需要注意的是，<strong>目前 AI 编码领域并没有一个所有厂商完全统一的术语标准</strong>，各家叫法存在细微差异。</p><p>如果你需要在多个生态之间切换，或者编写跨平台的团队规范（如 <code>AGENTS.md</code>），请务必参考下方的跨平台术语对照表：</p><table tabindex="0"><thead><tr><th style="text-align:left;">概念层级</th><th style="text-align:left;">OpenAI 生态 (ChatGPT / API)</th><th style="text-align:left;">Anthropic 生态 (Claude Code)</th><th style="text-align:left;">行业通用度与备注</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>单次完整的对话窗口</strong></td><td style="text-align:left;"><strong>Thread</strong> (官方 API 术语) / Chat</td><td style="text-align:left;"><strong>Session</strong> (官方标识如 <code>session_xxx</code>)</td><td style="text-align:left;">⚠️ <strong>存在分歧</strong>。在 Claude Code 中，用户口头常说的 Thread 实际在系统底层被定义为 Session。不能直接混用。</td></tr><tr><td style="text-align:left;"><strong>一次“用户提问 → 助手回复”</strong></td><td style="text-align:left;"><strong>Turn</strong></td><td style="text-align:left;"><strong>Turn</strong> (系统内置指令反复强调的词汇)</td><td style="text-align:left;">✅ <strong>高度通用</strong>。无论是对话系统研究还是各家大厂的底层 Prompt，都通用此概念。</td></tr><tr><td style="text-align:left;"><strong>跨越多轮/多窗口的宏观目标</strong></td><td style="text-align:left;">偏向自定义（常称 <strong>Task</strong>）</td><td style="text-align:left;"><strong>Task</strong> (有后台追踪状态) / <strong>Agent</strong> (派生独立会话)</td><td style="text-align:left;">⚠️ <strong>无强制统一标准</strong>。这往往不是大模型强加的概念，而是依赖研发团队自己的组织方式（如“阶段 A”、“子任务 B”）。</td></tr></tbody></table><h4 id="💡-跨平台团队协作的避坑建议" tabindex="-1">💡 跨平台团队协作的避坑建议 <a class="header-anchor" href="#💡-跨平台团队协作的避坑建议" aria-label="Permalink to &quot;💡 跨平台团队协作的避坑建议&quot;">​</a></h4><ol><li><strong>交流时认准“Turn”</strong>：当你需要限制 AI 的输出长度、干预步骤时，使用 <strong>Turn</strong>（轮）是最安全、最准确的业界通用词汇（例如：“Limit your analysis to this turn”）。</li><li><strong>入乡随俗的窗口称呼</strong>：在 OpenAI/Codex 生态写提示词时用 <strong>Thread</strong>；而在 Claude Code 中排查日志或建立协调代理时，请认准 <strong>Session</strong> 标识。</li><li><strong>“任务 (Task)”需要自己定义边界</strong>：既然各家对“跨窗口的更大任务”没有统一的强制指代，团队就必须在工程规范（如 Git Worktree 命名或项目根目录的规则文件）中明确“一个 Task 包含哪些交付物”，而不是指望大模型去自动理解你的项目宏观边界。</li></ol><h3 id="_9-深度解析-claude-code-中的-session-与额度重置机制" tabindex="-1">9. 深度解析：Claude Code 中的“Session”与额度重置机制 <a class="header-anchor" href="#_9-深度解析-claude-code-中的-session-与额度重置机制" aria-label="Permalink to &quot;9. 深度解析：Claude Code 中的“Session”与额度重置机制&quot;">​</a></h3><p>在使用 Claude Code 时，很多开发者会对 <code>/usage</code> 命令返回的 <code>current session</code> 感到困惑。因为在 Anthropic 的体系中，<strong>“Session”这个词被重载了，用在了两个完全不同的概念上。</strong></p><h4 id="a-概念解耦-对话容器-vs-计费窗口" tabindex="-1">A. 概念解耦：对话容器 vs 计费窗口 <a class="header-anchor" href="#a-概念解耦-对话容器-vs-计费窗口" aria-label="Permalink to &quot;A. 概念解耦：对话容器 vs 计费窗口&quot;">​</a></h4><p>遇到“Session”一词，必须结合上下文来判断其真实含义，两者绝不能混淆：</p><ol><li><p><strong>对话 Session（交互容器）</strong></p><ul><li><strong>含义</strong>：一个终端窗口里包含多个 Turn（轮）的一次完整多轮对话。</li><li><strong>证据</strong>：Claude Code 系统底层生成的标识符即为 <code>session_xxx</code> 格式。</li><li><strong>生命周期</strong>：当你执行 <code>/clear</code> 命令时，会清空当前终端的上下文历史，等同于开启了一次全新的对话交互。</li></ul></li><li><p><strong>用量 Session（计费与限流窗口）</strong></p><ul><li><strong>含义</strong>：这是 Anthropic 订阅套餐（Pro/Max/Team）的<strong>滚动时间限流窗口</strong>。</li><li><strong>机制</strong>：从你在这个窗口内产生第一次用量算起，以 <strong>5 小时</strong>为一个周期。周期内容量封顶，超限后必须等这 5 小时耗尽才会重置恢复。</li><li><strong>独立性</strong>：这个用量窗口与你开了多少个终端对话、执行了多少次 <code>/clear</code> 毫无关系。网页版 (claude.ai)、桌面版 (Claude Desktop) 和终端 (Claude Code) <strong>共享同一个用量池</strong>。</li></ul></li></ol><h4 id="b-5-小时用量-session-的容量差异" tabindex="-1">B. 5 小时用量 Session 的容量差异 <a class="header-anchor" href="#b-5-小时用量-session-的容量差异" aria-label="Permalink to &quot;B. 5 小时用量 Session 的容量差异&quot;">​</a></h4><p>同样是“5 小时重置一次”，不同订阅套餐的可用消息额度差异巨大。以下是基于官方数据的容量倍数参考（实际条数受上下文长度和系统负载影响）：</p><table tabindex="0"><thead><tr><th style="text-align:left;">订阅套餐</th><th style="text-align:left;">每 5 小时 Session 用量 (相对 Pro 倍数)</th><th style="text-align:left;">容量预估与说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pro</strong></td><td style="text-align:left;">1x (基准)</td><td style="text-align:left;">高峰时段限额至少是免费版的 5 倍。</td></tr><tr><td style="text-align:left;"><strong>Team 标准席位</strong></td><td style="text-align:left;">1.25x</td><td style="text-align:left;">额度按“每个成员”<strong>单独计算</strong>，并非全团队共享。</td></tr><tr><td style="text-align:left;"><strong>Max 5x ($100/月)</strong></td><td style="text-align:left;">5x</td><td style="text-align:left;">大约每 5 小时至少 225 条消息。</td></tr><tr><td style="text-align:left;"><strong>Team 高级席位</strong></td><td style="text-align:left;">6.25x</td><td style="text-align:left;">同样按“每个成员”单独计算。</td></tr><tr><td style="text-align:left;"><strong>Max 20x ($200/月)</strong></td><td style="text-align:left;"><strong>20x</strong></td><td style="text-align:left;">大约每 5 小时至少 900 条消息。</td></tr></tbody></table><blockquote><p>⚠️ <strong>关键注意</strong>：</p><ol><li>上述表格中的“大约消息数”不是恒定值，官方声明其取决于消息长度、对话上下文深度及 Claude 当前的系统容量。</li><li>除了这层滚动的 5 小时 Session 限额外，所有付费套餐还同时受到一个<strong>跨全部模型的每周限额</strong>约束。两者并存，任一触顶都会受限。</li></ol></blockquote>',71)])])}const f=e(s,[["render",o]]);export{y as __pageData,f as default};
